  ('gs-satt-board-dhaka-2025-mcq-020', 'class9-10-general-science-bn-guide', 'satt-gs-board-2025.pdf p21', 'কৃত্রিম তন্ত্রর মধ্যে রেয়ন – i. প্রধান এবং প্রথম তন্তু ii. লঘু এসিডের সাথে তেমন কোনো বিক্রিয়া করেনা iii. খুব হালকা ও শক্ত নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, null, 1, false, 'gs-satt-board-dhaka-2025-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই', null, 'dhaka', 2025, true),
