  ('gs-satt-board-dhaka-2025-mcq-025', 'class9-10-general-science-bn-guide', 'satt-gs-board-2025.pdf p21', 'নদী শাসনের অংশ হচ্ছে- i. পানি প্রবাহের জন্য সুইস গেট নির্মাণ ii. নদীর পাড়ে গাছ লাগানো iii. নদীর পাড়ে কাঠ বা বাঁশের ঢিবি তৈরি করা নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, null, 1, false, 'gs-satt-board-dhaka-2025-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই', null, 'dhaka', 2025, true),
