  ('gs-satt-board-jessore-2025-mcq-030', 'class9-10-general-science-bn-guide', 'satt-gs-board-2025.pdf p12', 'কেমোথেরাপির পার্শ্ব প্রতিক্রিয়া হলো- i.. হৃৎপিণ্ড আকারে বড় হয়ে যাওয়া ii. রক্ত কণিকা উৎপাদনে বাধাগ্রস্ত হওয়া iii. খাবার হজম না হওয়া নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, null, 1, false, 'gs-satt-board-jessore-2025-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই', null, 'jessore', 2025, true),
